// src/components/WalletGì vậyConnect.js
import React, { useState, useEffect } from 'react';
// Ethers v6 imports: BrowserProvider và formatEther được import trực tiếp
import { BrowserProvider, formatEther } from 'ethers'; 
import detectEthereumProvider from '@metamask/detect-provider';

function WalletConnect({ onWalletConnected }) {
  // ===== STATE MANAGEMENT =====
  const [account, setAccount] = useState(null);
  const [balance, setBalance] = useState(null);
  const [network, setNetwork] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [provider, setProvider] = useState(null);
  const [isMetaMaskInstalled, setIsMetaMaskInstalled] = useState(false);

  // ===== KIỂM TRA METAMASK KHI LOAD TRANG =====
  useEffect(() => {
    // Sử dụng một hàm async bên trong useEffect
    const initialize = async () => {
      await checkMetaMaskInstalled();
      await checkPreviousConnection();
    };
    initialize();
  }, []);

  // ===== KIỂM TRA METAMASK ĐÃ CÀI ĐẶT CHƯA =====
  const checkMetaMaskInstalled = async () => {
    const detectedProvider = await detectEthereumProvider();
    setIsMetaMaskInstalled(!!detectedProvider);
    
    if (detectedProvider) {
      // Ethers v6: Sử dụng BrowserProvider thay cho Web3Provider
      setProvider(new BrowserProvider(detectedProvider));
    }
  };

  // ===== KIỂM TRA KẾT NỐI TRƯỚC ĐÓ =====
  const checkPreviousConnection = async () => {
    if (window.ethereum) {
      try {
        const accounts = await window.ethereum.request({ 
          method: 'eth_accounts' 
        });
        
        if (accounts.length > 0 && provider) {
          await handleAccountChanged(accounts[0]);
        }
      } catch (error) {
        console.error("Lỗi kiểm tra kết nối cũ:", error);
      }
    }
  };
  
  // Effect để xử lý khi provider thay đổi
  useEffect(() => {
    if (provider) {
      checkPreviousConnection();
    }
  }, [provider]);

  // ===== XỬ LÝ KHI TÀI KHOẢN THAY ĐỔI =====
  const handleAccountChanged = async (newAccount) => {
    if (!newAccount) {
      setAccount(null);
      setBalance(null);
      setNetwork(null);
      if (onWalletConnected) onWalletConnected(null);
      return;
    }

    setAccount(newAccount);
    
    if (provider) {
      try {
        const balanceBigInt = await provider.getBalance(newAccount);
        // Ethers v6: Sử dụng formatEther trực tiếp
        const formattedBalance = formatEther(balanceBigInt);
        setBalance(formattedBalance);
        
        const networkInfo = await provider.getNetwork();
        setNetwork(networkInfo);
        
        if (onWalletConnected) {
          onWalletConnected({
            account: newAccount,
            balance: formattedBalance,
            // Ethers v6: chainId là kiểu bigint, chuyển sang Number
            chainId: Number(networkInfo.chainId) 
          });
        }
      } catch (error) {
        console.error("Lỗi lấy thông tin:", error);
        setError("Không thể lấy thông tin tài khoản.");
      }
    }
  };

  // ===== KẾT NỐI VÍ METAMASK =====
  const connectWallet = async () => {
    setError('');
    setLoading(true);

    if (!provider) {
      setError("MetaMask chưa được cài đặt hoặc không được phát hiện.");
      setLoading(false);
      return;
    }

    try {
      // Yêu cầu quyền truy cập tài khoản
      const accounts = await provider.send("eth_requestAccounts", []);

      if (accounts.length === 0) {
        throw new Error("Không tìm thấy tài khoản nào");
      }

      await handleAccountChanged(accounts[0]);

      // Lắng nghe sự kiện thay đổi tài khoản
      if (window.ethereum) {
        window.ethereum.on('accountsChanged', (accounts) => handleAccountChanged(accounts[0]));
        // Lắng nghe sự kiện thay đổi mạng
        window.ethereum.on('chainChanged', () => {
          window.location.reload();
        });
      }

    } catch (error) {
      console.error("Lỗi kết nối:", error);
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  // ===== NGẮT KẾT NỐI =====
  const disconnectWallet = () => {
    setAccount(null);
    setBalance(null);
    setNetwork(null);
    if (onWalletConnected) onWalletConnected(null);
  };

  // ===== RÚT GỌN ĐỊA CHỈ VÍ =====
  const shortenAddress = (address) => {
    if (!address) return '';
    return `${address.slice(0, 6)}...${address.slice(-4)}`;
  };

  // ===== LẤY TÊN MẠNG =====
  const getNetworkName = (chainId) => {
    if (!chainId) return 'Unknown';
    
    const networks = {
      1: 'Ethereum Mainnet',
      5: 'Goerli',
      11155111: 'Sepolia',
      1337: 'Local Hardhat',
      31337: 'Local Hardhat'
    };
    
    return networks[chainId] || `Chain ID: ${chainId}`;
  };

  // ===== GIAO DIỆN =====
  return (
    <div className="wallet-connect-container">
      <div className="wallet-header">
        <h2>🔌 Kết nối ví MetaMask</h2>
        {!isMetaMaskInstalled && (
          <div className="warning-badge">
            ⚠️ Chưa cài MetaMask
          </div>
        )}
      </div>

      <div className="wallet-content">
        {!account ? (
          // TRƯỜNG HỢP CHƯA KẾT NỐI
          <div className="connect-section">
            <div className="wallet-icon">🦊</div>
            <h3>Kết nối với MetaMask</h3>
            <p className="connect-description">
              Kết nối ví MetaMask của bạn để bắt đầu tham gia đấu giá
            </p>
            
            {!isMetaMaskInstalled && (
              <div className="install-metamask">
                <p>Bạn chưa cài đặt MetaMask?</p>
                <a 
                  href="https://metamask.io/download/" 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="install-link"
                >
                  📥 Tải MetaMask ngay
                </a>
              </div>
            )}
            
            <button 
              onClick={connectWallet}
              disabled={loading || !isMetaMaskInstalled}
              className={`connect-btn ${loading ? 'loading' : ''}`}
            >
              {loading ? (
                <>
                  <span className="spinner">⏳</span>
                  Đang kết nối...
                </>
              ) : (
                <>
                  <span>🦊</span>
                  Kết nối MetaMask
                </>
              )}
            </button>
            
            {error && (
              <div className="error-message">
                ❌ {error}
              </div>
            )}
          </div>
        ) : (
          // TRƯỜNG HỢP ĐÃ KẾT NỐI
          <div className="wallet-info">
            <div className="info-card">
              <div className="info-icon">👤</div>
              <div className="info-content">
                <span className="info-label">Tài khoản</span>
                <span className="info-value address" title={account}>
                  {shortenAddress(account)}
                </span>
                <button 
                  className="copy-btn"
                  onClick={() => navigator.clipboard.writeText(account)}
                  title="Copy địa chỉ"
                >
                  📋
                </button>
              </div>
            </div>

            <div className="info-card">
              <div className="info-icon">💰</div>
              <div className="info-content">
                <span className="info-label">Số dư</span>
                <span className="info-value balance">
                  {balance ? parseFloat(balance).toFixed(4) : '0'} ETH
                </span>
              </div>
            </div>

            <div className="info-card">
              <div className="info-icon">🌐</div>
              <div className="info-content">
                <span className="info-label">Mạng</span>
                <span className="info-value network">
                  {getNetworkName(network?.chainId)}
                </span>
              </div>
            </div>

            <div className="connection-status">
              <div className="status-dot connected"></div>
              <span>Đã kết nối</span>
            </div>

            <button 
              onClick={disconnectWallet}
              className="disconnect-btn"
            >
              🔌 Ngắt kết nối
            </button>
          </div>
        )}
      </div>

      {!account && (
        <div className="guide-section">
          <h4>📚 Hướng dẫn nhanh:</h4>
          <ol>
            <li>Cài đặt MetaMask (nếu chưa có)</li>
            <li>Tạo ví hoặc import ví cũ</li>
            <li>Chuyển sang mạng Sepolia Testnet</li>
            <li>Nhận ETH test từ faucet</li>
            <li>Nhấn nút "Kết nối MetaMask"</li>
          </ol>
        </div>
      )}
    </div>
  );
}

export default WalletConnect;
